def pg_wait(self):
        """Wait for the DB to be fired up."""
        self.log.info("Waiting for PostgreSQL to be ready")
        while True:
            try:
                self.pg_conn.connect()
                break
            except psycopg2.OperationalError:
                self.log.info("Waiting for PostgreSQL to be ready")
                time.sleep(1)

